function fit(view=$('camera-view').value){const box=new THREE.Box3();for(const o of meshes(workshop.root).filter(visible))box.expandByObject(o);if(box.isEmpty())box.setFromCenterAndSize(new THREE.Vector3(0,0,80),new THREE.Vector3(200,200,160));const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),max=Math.max(...size.toArray(),10);const directions={iso:[1.3,-1.8,1.1],front:[0,-1,0],back:[0,1,0],left:[-1,0,0],right:[1,0,0],top:[0,-.00001,1],bottom:[0,-.00001,-1]};const aspect=viewport.clientWidth/Math.max(viewport.clientHeight,1);const distance=max/Math.min(aspect,1)/Math.tan(THREE.MathUtils.degToRad(21))*.85;camera.position.copy(center).addScaledVector(new THREE.Vector3(...directions[view]).normalize(),distance);camera.up.set(0,0,1);controls.target.copy(center);camera.near=Math.max(.01,distance/10000);camera.far=Math.max(distance*100,10000);if(camera.isOrthographicCamera){const h=max*1.5/Math.min(aspect,1);camera.left=-h*aspect/2;camera.right=h*aspect/2;camera.top=h/2;camera.bottom=-h/2;camera.zoom=1;}camera.updateProjectionMatrix();controls.update();}
