function resize(){invalidate();const w=viewport.clientWidth,h=Math.max(1,viewport.clientHeight);renderer.setSize(w,h);labelRenderer.setSize(w,h);perspective.aspect=w/h;perspective.updateProjectionMatrix();if(camera.isOrthographicCamera){const height=camera.top-camera.bottom;camera.left=-height*w/h/2;camera.right=height*w/h/2;camera.updateProjectionMatrix();}}
