let frameHandle=0,frameCount=0,lastFrame=0;
function invalidate(){if(!document.hidden&&!frameHandle)frameHandle=requestAnimationFrame(loop);}
function loop(t){frameHandle=0;if(document.hidden)return;if(t-lastFrame<30){invalidate();return;}const delta=Math.min((t-lastFrame)/1000,.1);lastFrame=t;let active=false;if(playing){setExplode((Math.sin(t/1800-Math.PI/2)+1)*75,false);refreshAnnotations();active=true;}if(jointUI?.tick(t))active=true;controls.autoRotate=turntable;controls.autoRotateSpeed=.6;const moved=controls.update(delta);renderer.render(scene,camera);labelRenderer.render(scene,camera);frameCount++;if(active||turntable||moved)invalidate();}
