function setExplode(value,refresh=true){invalidate();explosion=Number(value);$('explode').value=String(explosion);const objects=workshop.root.children.filter(o=>o.userData.component);const center=new THREE.Box3().setFromObject(workshop.root).getCenter(new THREE.Vector3());for(let i=0;i<objects.length;i++){const o=objects[i];if(locked(o))continue;if(!o.userData.explodeBase)o.userData.explodeBase=o.position.toArray();if(!o.userData.explodeDirection){const c=new THREE.Box3().setFromObject(o).getCenter(new THREE.Vector3()).sub(center);if(c.lengthSq()<.01)c.set(Math.cos(i*2.4),Math.sin(i*2.4),.4);o.userData.explodeDirection=c.normalize().toArray();}o.position.fromArray(o.userData.explodeBase).addScaledVector(new THREE.Vector3().fromArray(o.userData.explodeDirection),explosion);if(!explosion){delete o.userData.explodeBase;delete o.userData.explodeDirection;}}updateTransform();if(refresh){refreshHelpers();refreshAnnotations();}}
function applySection(){const axis=$('section-axis').value;plane.normal.set(axis==='x'?1:0,axis==='y'?1:0,axis==='z'?1:0);plane.constant=-Number($('section-offset').value||0);workshop.root.traverse(o=>{if(o.isMesh)for(const m of [o.material].flat()){m.clippingPlanes=axis==='off'?[]:[plane];m.needsUpdate=true;}});refreshHelpers();}
